<main class="section"><div class="section-head"><div><span class="eyebrow">Finanzen</span><h1>Wallet</h1></div></div><div class="dash-grid"><?php $boxes=['Vorgemerkt'=>$wallet['balance_reserved']??0,'In Prüfung'=>$wallet['balance_in_review']??0,'Verfügbar'=>$wallet['balance_available']??0];foreach($boxes as $label=>$value):?><div class="card dash-card"><span><?=App\Core\View::e($label)?></span><strong><?=number_format((float)$value,2,',','.')?> €</strong></div><?php endforeach;?></div><h2>Buchungen</h2><div class="worklist"><?php foreach($entries as $e):?><div class="work-row"><div><b><?=App\Core\View::e($e['entry_type'])?></b><span><?=App\Core\View::e($e['status'])?> · <?=date('d.m.Y H:i',strtotime($e['created_at']))?></span></div><strong><?=number_format((float)$e['amount'],2,',','.')?> €</strong></div><?php endforeach;?><?php if(!$entries):?><div class="empty">Noch keine Wallet-Buchungen.</div><?php endif;?></div></main>